#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    int T;    cin >> T;     while(T--){        int n;        cin >> n ;                int d = -1;                //first try to find first min divisor        for(int i = 2; i * i <= n ; i ++){            if(n % i == 0){                d = i;                break;            }        }                if(d == -1){            //then it is a prime number             //so LCM = (1 , n - 1);                        cout << 1 << " " << n - 1 << endl;            continue;        }        else{            //d is the smallest divisor             // n/d => largest divisor;                        //so we get this divisor            int g = n / d;                        cout << g << " " << n - g << endl;        }                    }}